mapper.select:
SELECT SQL_CALC_FOUND_ROWS ROW_NUMBER() OVER (ORDER BY g5so.od_time DESC) AS row_num, g5so.mb_id,pih.pet_type_cd,puch.urine_check_history_id, g5so.od_id, g5so.od_b_name, g5so.od_b_tel, CONCAT(g5so.od_b_addr1, ' ', g5so.od_b_addr2, ' ', g5so.od_b_addr3,' ',g5so.od_b_zip1, g5so.od_b_zip2) AS address, g5sc.ct_id, g5sc.it_id, g5so.od_cart_count, CASE WHEN g5si.it_3 = '' THEN '1000' ELSE '1000' END AS od_cart_weight, pcc.code_nm AS od_delivery_company, g5so.od_invoice, g5so.od_status, g5so.od_time FROM g5_shop_order g5so INNER JOIN g5_shop_cart g5sc ON g5so.od_id = g5sc.od_id INNER JOIN g5_shop_item g5si ON g5sc.it_id = g5si.it_id INNER JOIN pet_urine_check_history puch ON g5sc.urine_check_history_id = puch.urine_check_history_id INNER JOIN pet_info_history pih ON puch.pet_history_id = pih.pet_history_id INNER JOIN pet_common_code pcc ON g5so.od_delivery_company = pcc.code_cd WHERE g5so.od_status IN ('준비', '배송', '완료') AND g5si.it_10 = 'use' AND g5sc.pet_history_id is not null
AND DATE_FORMAT(g5so.od_time, '%Y-%m-%d') >= #{startDate}
AND DATE_FORMAT(g5so.od_time, '%Y-%m-%d') <= #{endDate}
AND g5so.od_status = #{searchType}
GROUP BY g5so.od_id LIMIT #{pageNo} , #{pageSize}

SELECT COUNT(*)
FROM g5_shop_order
WHERE od_id = #{odId}

SELECT COUNT(*)
FROM pet_ship_invoice
WHERE od_id = #{odId} OR od_invoice = #{odInvoice}

SELECT SQL_CALC_FOUND_ROWS ROW_NUMBER() OVER (ORDER BY g5so.od_time DESC) AS row_num, g5so.od_id, g5so.od_b_name, g5so.od_b_tel, CONCAT(g5so.od_b_addr1, ' ', g5so.od_b_addr2, ' ', g5so.od_b_addr3,' ',g5so.od_b_zip1, g5so.od_b_zip2) AS address, g5sc.it_id, g5so.od_cart_count, CASE WHEN g5si.it_3 = '' THEN '1000' ELSE '1000' END AS od_cart_weight, pcc.code_nm AS od_delivery_company, g5so.od_invoice, g5so.od_status, g5so.od_time FROM g5_shop_order g5so INNER JOIN g5_shop_cart g5sc ON g5so.od_id = g5sc.od_id INNER JOIN g5_shop_item g5si ON g5sc.it_id = g5si.it_id INNER JOIN pet_common_code pcc ON g5so.od_delivery_company = pcc.code_cd WHERE g5so.od_status IN ('준비', '배송', '완료') AND g5si.it_10 = 'use'
AND DATE_FORMAT(g5so.od_time, '%Y-%m-%d') >= #{startDate}
AND DATE_FORMAT(g5so.od_time, '%Y-%m-%d') <= #{endDate}
AND g5so.od_status = #{searchType}
GROUP BY g5so.od_id LIMIT #{limit} OFFSET #{offset};

SELECT COUNT(DISTINCT g5so.od_id) AS total_cnt
FROM g5_shop_order g5so
INNER JOIN g5_shop_cart g5sc ON g5so.od_id = g5sc.od_id
INNER JOIN g5_shop_item g5si ON g5sc.it_id = g5si.it_id
WHERE g5so.od_status IN ('준비', '배송', '완료') AND g5si.it_10 = 'use'

  AND DATE_FORMAT(g5so.od_time, '%Y-%m-%d') >= #{startDate}


   AND DATE_FORMAT(g5so.od_time, '%Y-%m-%d') <= #{endDate}


  AND g5so.od_status = #{searchType}

SELECT
    product_cd, product_nm
FROM pet_base_material
WHERE ingredient_reg_num = #{ingredientRegNum}
GROUP BY product_cd, product_nm;
